export type Food = {
  name: string;
  mealType: 'Breakfast' | 'Lunch' | 'Dinner' | 'Snack';
  cuisine: string;
  category: string;
  caloriesPerCup: number;
  proteinPerCup: number;
  carbsPerCup: number;
  fatPerCup: number;
  emoji?: string;
  servingSize?: string;
};

export function foodEmoji(food: Food): string {
  if (food.emoji) return food.emoji;
  const n = food.name.toLowerCase();
  const c = food.category.toLowerCase();
  if (n.includes('chicken')) return '🍗';
  if (n.includes('fish') || n.includes('salmon') || n.includes('tuna') || n.includes('moilee')) return '🐟';
  if (n.includes('prawn') || n.includes('shrimp')) return '🦐';
  if (n.includes('mutton') || n.includes('beef') || n.includes('lamb')) return '🍖';
  if (n.includes('egg')) return '🥚';
  if (n.includes('paneer') || n.includes('cheese')) return '🧀';
  if (n.includes('pizza')) return '🍕';
  if (n.includes('burger')) return '🍔';
  if (n.includes('sandwich')) return '🥪';
  if (n.includes('pasta') || n.includes('spaghetti') || n.includes('penne') || n.includes('lasagna') || n.includes('macaroni')) return '🍝';
  if (n.includes('noodle') || n.includes('ramen') || n.includes('hakka')) return '🍜';
  if (n.includes('dosa') || n.includes('chilla') || n.includes('cheela')) return '🥞';
  if (n.includes('idli')) return '⚪';
  if (n.includes('biryani') || n.includes('rice') || n.includes('pulao') || n.includes('pongal')) return '🍚';
  if (n.includes('roti') || n.includes('naan') || n.includes('paratha') || n.includes('chapati') || n.includes('phulka') || n.includes('kulcha') || n.includes('puri') || n.includes('bread')) return '🫓';
  if (n.includes('salad')) return '🥗';
  if (n.includes('soup') || n.includes('rasam') || n.includes('sambar')) return '🥣';
  if (n.includes('dal') || n.includes('lentil')) return '🍲';
  if (n.includes('curry') || n.includes('masala') || n.includes('korma')) return '🍛';
  if (n.includes('tea') || n.includes('chai')) return '🍵';
  if (n.includes('coffee')) return '☕';
  if (n.includes('lassi') || n.includes('buttermilk') || n.includes('milk') || n.includes('yogurt') || n.includes('curd')) return '🥛';
  if (n.includes('smoothie') || n.includes('juice')) return '🥤';
  if (n.includes('banana')) return '🍌';
  if (n.includes('apple')) return '🍎';
  if (n.includes('mango')) return '🥭';
  if (n.includes('fruit')) return '🍎';
  if (n.includes('almond') || n.includes('nut') || n.includes('trail mix') || n.includes('peanut')) return '🥜';
  if (n.includes('oat') || n.includes('muesli') || n.includes('granola') || n.includes('cereal')) return '🥣';
  if (n.includes('whey') || n.includes('protein bar') || n.includes('protein')) return '💪';
  if (n.includes('chocolate')) return '🍫';
  if (n.includes('popcorn')) return '🍿';
  if (n.includes('fries') || n.includes('finger')) return '🍟';
  if (n.includes('nugget')) return '🍗';
  if (n.includes('steak')) return '🥩';
  if (n.includes('sushi') || n.includes('dim sum') || n.includes('momo')) return '🥟';
  if (n.includes('spring roll')) return '🌯';
  if (n.includes('pancake') || n.includes('waffle')) return '🥞';
  if (n.includes('toast') || n.includes('avocado')) return '🍞';
  if (n.includes('waffle')) return '🧇';
  if (n.includes('jalebi') || n.includes('halwa') || n.includes('sheera') || n.includes('sweet') || n.includes('dessert')) return '🍮';
  if (n.includes('samosa') || n.includes('kachori') || n.includes('pakora') || n.includes('bhajji') || n.includes('vada') || n.includes('snack')) return '🥘';
  if (n.includes('vegetable') || n.includes('sabzi') || n.includes('bharta') || n.includes('gobi') || n.includes('bhindi') || n.includes('aloo')) return '🥕';
  if (c.includes('drink') || c.includes('beverage')) return '🥤';
  return '🍽️';
}

export function foodServingSize(food: Food): string {
  if (food.servingSize) return food.servingSize;
  const c = food.category.toLowerCase();
  if (c.includes('drink') || c.includes('beverage')) return '1 glass (250ml)';
  if (c.includes('soup')) return '1 bowl (250ml)';
  if (c.includes('flatbread') || c.includes('bread') || c.includes('roti') || c.includes('naan') || c.includes('paratha')) return '1 piece';
  if (c.includes('pancake') || c.includes('crepe') || c.includes('dosa')) return '1 piece';
  if (c.includes('dumpling') || c.includes('momos')) return '4 pieces';
  if (c.includes('snack') || c.includes('sweet')) return '1 serving';
  return '1 cup (200g)';
}

